#!/bin/bash
set -e
FIXTURE="audit/tests/fixtures/inventory-test"

rm -rf "$FIXTURE"
mkdir -p "$FIXTURE/lib/agent/providers"
mkdir -p "$FIXTURE/lib/routes"
mkdir -p "$FIXTURE/mcp/tools"
mkdir -p "$FIXTURE/db/migrations"
mkdir -p "$FIXTURE/db/migrations-sqlite"
mkdir -p "$FIXTURE/db/sqlite"
mkdir -p "$FIXTURE/db/postgres"
mkdir -p "$FIXTURE/public/locales"
mkdir -p "$FIXTURE/public/scripts"
mkdir -p "$FIXTURE/tests/unit"
mkdir -p "$FIXTURE/tests/integration"
mkdir -p "$FIXTURE/skills/test-skill"
mkdir -p "$FIXTURE/var"
mkdir -p "$FIXTURE/coverage"
mkdir -p "$FIXTURE/.hidden-dir"

touch "$FIXTURE/lib/server.js"
touch "$FIXTURE/lib/config.js"
touch "$FIXTURE/lib/agent.js"
touch "$FIXTURE/lib/tool.js"
touch "$FIXTURE/lib/helper.js"
touch "$FIXTURE/mcp/index.js"
touch "$FIXTURE/mcp/server.js"
touch "$FIXTURE/db/index.js"
touch "$FIXTURE/db/sqlite.js"
touch "$FIXTURE/db/postgres.js"
touch "$FIXTURE/db/types.js"
touch "$FIXTURE/db/sqlite/store.js"
touch "$FIXTURE/db/postgres/store.js"
touch "$FIXTURE/public/scripts/app.js"
touch "$FIXTURE/public/scripts/ui.js"
touch "$FIXTURE/skills/test-skill/SKILL.md"
touch "$FIXTURE/skills/test-skill/helper.js"
touch "$FIXTURE/lib/agent/providers/anthropic.js"
touch "$FIXTURE/lib/agent/providers/deepseek.js"
touch "$FIXTURE/lib/agent/providers/llamacpp.js"
touch "$FIXTURE/lib/routes/api.js"
touch "$FIXTURE/lib/routes/paths.js"
touch "$FIXTURE/mcp/tools/memory.js"
touch "$FIXTURE/mcp/tools/files.js"
touch "$FIXTURE/db/migrations/001_core.sql"
touch "$FIXTURE/db/migrations/002_agent_jobs.sql"
touch "$FIXTURE/db/migrations-sqlite/001_core.sql"
touch "$FIXTURE/db/migrations-sqlite/002_agent_jobs.sql"
touch "$FIXTURE/file with spaces.txt"
touch "$FIXTURE/public/locales/en.json"
touch "$FIXTURE/public/locales/bg.json"
touch "$FIXTURE/public/locales/de.json"
touch "$FIXTURE/tests/unit/core.test.js"
touch "$FIXTURE/tests/unit/config.test.js"
touch "$FIXTURE/tests/integration/api.test.js"
touch "$FIXTURE/var/session.log"
touch "$FIXTURE/coverage/lcov.info"
touch "$FIXTURE/.hidden-dir/secret.txt"

cat > "$FIXTURE/.gitignore" << 'GITIGNORE'
var/
coverage/
GITIGNORE

cd "$FIXTURE" && git init -q && git config user.email "test@aperio.dev" && git config user.name "Test"
git add -A && git commit -m "test fixture" -q
echo "FIXTURE_READY at $FIXTURE"
